[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<title>Frontier AI Models Compared - Infographic Poster</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  width: 2384px;
  height: 3370px;
  background: #0b0f19;
  font-family: 'Inter', -apple-system, sans-serif;
  color: #e2e8f0;
  overflow: hidden;
}

.poster {
  width: 2384px;
  height: 3370px;
  padding: 80px 100px 60px;
  display: flex;
  flex-direction: column;
  position: relative;
  background:
    radial-gradient(ellipse 80% 50% at 20% 10%, rgba(59,130,246,0.06) 0%, transparent 60%),
    radial-gradient(ellipse 60% 40% at 80% 85%, rgba(20,184,166,0.05) 0%, transparent 60%),
    #0b0f19;
}

/* ─── HEADER ─── */
.header {
  text-align: center;
  margin-bottom: 48px;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.header .source-tag {
  display: inline-block;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: #38bdf8;
  margin-bottom: 20px;
  padding: 8px 24px;
  border: 1px solid rgba(56,189,248,0.3);
  border-radius: 6px;
  background: rgba(56,189,248,0.06);
}
.header h1 {
  font-size: 72px;
  font-weight: 800;
  line-height: 1.1;
  color: #f1f5f9;
  letter-spacing: -1.5px;
  margin-bottom: 16px;
}
.header h1 span { color: #38bdf8; }
.header .subtitle {
  font-size: 24px;
  color: #94a3b8;
  font-weight: 400;
  max-width: 1400px;
  margin: 0 auto;
  line-height: 1.5;
}

/* ─── HERO CALLOUTS ─── */
.hero-callouts {
  display: flex;
  gap: 32px;
  margin-bottom: 50px;
}
.callout-card {
  flex: 1;
  padding: 36px 40px;
  border-radius: 16px;
  position: relative;
  overflow: hidden;
}
.callout-card::before {
