  inset: 0;
  border-radius: 16px;
  border: 1px solid rgba(255,255,255,0.08);
  pointer-events: none;
}
.callout-card.intel {
  background: linear-gradient(135deg, rgba(59,130,246,0.12) 0%, rgba(59,130,246,0.03) 100%);
}
.callout-card.speed {
  background: linear-gradient(135deg, rgba(20,184,166,0.12) 0%, rgba(20,184,166,0.03) 100%);
}
.callout-card.cost {
  background: linear-gradient(135deg, rgba(251,191,36,0.12) 0%, rgba(251,191,36,0.03) 100%);
}
.callout-label {
  font-size: 16px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 10px;
}
.callout-card.intel .callout-label { color: #60a5fa; }
.callout-card.speed .callout-label { color: #2dd4bf; }
.callout-card.cost .callout-label { color: #fbbf24; }
.callout-value {
  font-size: 80px;
  font-weight: 900;
  line-height: 1;
  margin-bottom: 8px;
  font-family: 'JetBrains Mono', monospace;
}
.callout-card.intel .callout-value { color: #3b82f6; }
.callout-card.speed .callout-value { color: #14b8a6; }
.callout-card.cost .callout-value { color: #fbbf24; }
.callout-unit {
  font-size: 22px;
  font-weight: 500;
  color: #94a3b8;
}
.callout-context {
  font-size: 16px;
  color: #64748b;
  margin-top: 8px;
  line-height: 1.4;
}

/* ─── SECTION HEADERS ─── */
.section {
  margin-bottom: 40px;
}
.section-header {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}
.section-number {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  font-weight: 700;
  font-family: 'JetBrains Mono', monospace;
}
.section-title {
  font-size: 28px;
  font-weight: 700;
  color: #f1f5f9;
  letter-spacing: -0.5px;
}
.section-subtitle {
  font-size: 16px;
  color: #64748b;
  margin-left: auto;
  font-weight: 400;
}

/* ─── CHART CONTAINERS ─── */
.chart-row {
  display: flex;
  gap: 40px;
  margin-bottom: 40px;
}
.chart-panel {
  flex: 1;
  background: rgba(255,255,255,0.02);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 16px;
  padding: 32px 36px;
}
.chart-panel.full {
  width: 100%;
}

/* ─── BAR CHART STYLES ─── */
.bar-row {
  display: flex;
  align-items: center;
  margin-bottom: 14px;
  height: 38px;
}
.bar-label {
  width: 280px;
  font-size: 16px;
  font-weight: 500;
  color: #cbd5e1;
  text-align: right;
  padding-right: 20px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bar-track {
  flex: 1;
  height: 30px;
  background: rgba(255,255,255,0.03);
  border-radius: 6px;
  position: relative;
  overflow: hidden;
}
.bar-fill {
  height: 100%;
  border-radius: 6px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 12px;
  transition: width 0.3s;
}
.bar-val {
  font-size: 14px;
  font-weight: 700;
  color: #fff;
  font-family: 'JetBrains Mono', monospace;
  text-shadow: 0 1px 3px rgba(0,0,0,0.5);
}
.bar-val-outside {
  font-size: 14px;
  font-weight: 700;
  font-family: 'JetBrains Mono', monospace;
  margin-left: 12px;
  white-space: nowrap;
}

/* ─── BUBBLE CHART ─── */
.bubble-chart-container {
  position: relative;
  width: 100%;
  height: 620px;
  margin-top: 8px;
}
.bubble-chart-svg {
  width: 100%;
  height: 100%;
}

/* ─── TRADE-OFF SECTION ─── */
.tradeoff-section {
  margin-bottom: 36px;
}
.tradeoff-section .chart-panel {
  padding: 40px 48px;
  border: 1px solid rgba(56,189,248,0.15);
  background: rgba(56,189,248,0.02);
}

/* ─── INSIGHT CARDS ─── */
.insight-row {
  display: flex;
  gap: 24px;
  margin-top: 28px;
}
.insight-card {
  flex: 1;
  padding: 24px 28px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,0.06);
  background: rgba(255,255,255,0.02);
}
.insight-card .insight-tag {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 8px;
}
.insight-card .insight-model {
  font-size: 20px;
  font-weight: 700;
  color: #f1f5f9;
  margin-bottom: 6px;
}
.insight-card .insight-detail {
  font-size: 14px;
  color: #94a3b8;
  line-height: 1.5;
}

/* ─── METHODOLOGY ─── */
.methodology {
  margin-top: auto;
  padding: 28px 36px;
  background: rgba(255,255,255,0.02);
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: 12px;
}
.methodology h3 {
  font-size: 18px;
  font-weight: 700;
  color: #94a3b8;
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
}
.methodology p {
  font-size: 15px;
  color: #64748b;
  line-height: 1.6;
  max-width: 1800px;
}

/* ─── DIVIDERS ─── */
.divider {
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.08) 20%, rgba(255,255,255,0.08) 80%, transparent);
  margin: 8px 0 40px;
}

/* ─── FOOTER ─── */
.footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 28px;
  padding-top: 20px;
  border-top: 1px solid rgba(255,255,255,0.05);
}
.footer span {
  font-size: 14px;
  color: #475569;
}
</style>
</head>
<body>
<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="source-tag">Artificial Analysis Intelligence Index v4.0</div>
    <h1>Frontier AI Models Compared<br/><span>Intelligence, Speed & Cost</span></h1>
    <p class="subtitle">A data-driven comparison of the top 10 frontier AI language models — there is no single "best" model.<br/>The right choice depends on which dimension matters most.</p>
  </div>

  <!-- HERO CALLOUTS -->
  <div class="hero-callouts">
    <div class="callout-card intel">
      <div class="callout-label">Top Intelligence</div>
      <div class="callout-value">57</div>
      <div class="callout-unit">AA Index Score</div>
      <div class="callout-context">Gemini 3.1 Pro &amp; GPT-5.4 tied at the top</div>
    </div>
    <div class="callout-card speed">
      <div class="callout-label">Fastest Output</div>
      <div class="callout-value">206</div>
      <div class="callout-unit">tokens / sec</div>
      <div class="callout-context">gpt-oss-120B — but ranks last in intelligence</div>
    </div>
    <div class="callout-card cost">
      <div class="callout-label">Price Range</div>
      <div class="callout-value">33×</div>
      <div class="callout-unit">$0.30 → $10.00 / 1M tokens</div>
      <div class="callout-context">Budget to premium: a staggering gap</div>
    </div>
  </div>

  <div class="divider"></div>

  <!-- SECTION 1 & 2: Intelligence + Speed side by side -->
  <div class="chart-row">
    <!-- Intelligence -->
    <div class="chart-panel">
      <div class="section-header">
        <div class="section-number" style="background:rgba(59,130,246,0.15);color:#60a5fa;">1</div>
        <div class="section-title">Intelligence Rankings</div>
        <div class="section-subtitle">AA Index Score</div>
      </div>
      <div id="intel-chart"></div>
    </div>
    <!-- Speed -->
    <div class="chart-panel">
      <div class="section-header">
        <div class="section-number" style="background:rgba(20,184,166,0.15);color:#2dd4bf;">2</div>
        <div class="section-title">Output Speed</div>
        <div class="section-subtitle">tokens / sec</div>
      </div>
      <div id="speed-chart"></div>
    </div>
  </div>

  <!-- SECTION 3: Pricing -->
  <div class="section">
    <div class="chart-panel full">
      <div class="section-header">
        <div class="section-number" style="background:rgba(251,191,36,0.15);color:#fbbf24;">3</div>
        <div class="section-title">Pricing Landscape</div>
        <div class="section-subtitle">USD per 1M tokens (blended input/output)</div>
      </div>
      <div id="price-chart"></div>
    </div>
  </div>

  <!-- SECTION 4: Trade-off Analysis (HERO) -->
  <div class="tradeoff-section">
    <div class="chart-panel full">
      <div class="section-header">
        <div class="section-number" style="background:rgba(139,92,246,0.2);color:#a78bfa;">4</div>
        <div class="section-title" style="color:#a78bfa;">The Intelligence–Speed–Cost Trade-Off</div>
        <div class="section-subtitle">Bubble size = cost · X = speed · Y = intelligence</div>
      </div>
      <div class="bubble-chart-container">
        <svg class="bubble-chart-svg" id="bubble-svg"></svg>
      </div>

      <!-- Insight Cards -->
      <div class="insight-row">
        <div class="insight-card" style="border-color:rgba(59,130,246,0.2);">
          <div class="insight-tag" style="color:#60a5fa;">Best Intelligence</div>
          <div class="insight-model">Gemini 3.1 Pro / GPT-5.4</div>
          <div class="insight-detail">Tied at 57 — mid-to-high cost ($4.50–$5.60), moderate speed</div>
        </div>
        <div class="insight-card" style="border-color:rgba(20,184,166,0.2);">
          <div class="insight-tag" style="color:#2dd4bf;">Best Value</div>
          <div class="insight-model">gpt-oss-120B</div>
          <div class="insight-detail">Fastest (206 tok/s), cheapest ($0.30) — but lowest intelligence (33)</div>
        </div>
        <div class="insight-card" style="border-color:rgba(251,191,36,0.2);">
          <div class="insight-tag" style="color:#fbbf24;">Balanced Pick</div>
          <div class="insight-model">Gemini 3 Flash</div>
          <div class="insight-detail">Intelligence 46, speed 149 tok/s, cost $1.10 — strong middle ground</div>
        </div>
        <div class="insight-card" style="border-color:rgba(244,63,94,0.2);">
          <div class="insight-tag" style="color:#fb7185;">Premium Tier</div>
          <div class="insight-model">Claude Opus 4.6</div>
          <div class="insight-detail">Intelligence 53, but slowest (40 tok/s) and most expensive ($10.00)</div>
        </div>
      </div>
    </div>
  </div>

  <!-- METHODOLOGY -->
  <div class="methodology">
    <h3>About the Index</h3>
    <p>The Artificial Analysis Intelligence Index v4.0 aggregates performance across 10 independent evaluations: GDPval-AA, τ²-Bench Telecom, Terminal-Bench Hard, SciCode, AA-LCR, AA-Omniscience, IFBench, Humanity's Last Exam, GPQA Diamond, and CritPt. Scores represent a holistic measure of model capability spanning coding, agentic tasks, scientific reasoning, knowledge accuracy, hallucination resistance, and instruction following. All measurements are conducted independently under standardized conditions.</p>
  </div>

  <!-- FOOTER -->
  <div class="footer">
    <span>Data: artificialanalysis.ai · Intelligence Index v4.0</span>
    <span>Visualization generated May 2026</span>
  </div>

</div>

<script>
// ─── DATA ───
const models = [
  { name: 'Gemini 3.1 Pro Preview', short: 'Gemini 3.1 Pro', intel: 57, speed: 129, price: 4.50, color: '#3b82f6' },
  { name: 'GPT-5.4 (xhigh)',        short: 'GPT-5.4',        intel: 57, speed: 72,  price: 5.60, color: '#60a5fa' },
  { name: 'Claude Opus 4.6 (max)',   short: 'Claude Opus 4.6', intel: 53, speed: 40,  price: 10.00, color: '#f97316' },
  { name: 'Muse Spark',             short: 'Muse Spark',      intel: 52, speed: null, price: null, color: '#a78bfa' },
  { name: 'Claude Sonnet 4.6 (max)', short: 'Claude Sonnet 4.6', intel: 52, speed: 48, price: 6.00, color: '#fb923c' },
  { name: 'GLM-5.1',                short: 'GLM-5.1',         intel: 51, speed: 40,  price: 2.10, color: '#34d399' },
  { name: 'Grok 4.20 0309 v2',      short: 'Grok 4.20',       intel: 49, speed: 162, price: 3.00, color: '#f472b6' },
  { name: 'Gemini 3 Flash',         short: 'Gemini 3 Flash',  intel: 46, speed: 149, price: 1.10, color: '#2dd4bf' },
  { name: 'DeepSeek V3.2',          short: 'DeepSeek V3.2',   intel: 42, speed: 31,  price: 0.30, color: '#818cf8' },
  { name: 'NVIDIA Nemotron 3 Super', short: 'Nemotron 3',      intel: 36, speed: 193, price: 0.40, color: '#4ade80' },
  { name: 'gpt-oss-120B (high)',     short: 'gpt-oss-120B',    intel: 33, speed: 206, price: 0.30, color: '#94a3b8' },
];

// Intelligence data sorted by score desc
const intelData = [...models].sort((a, b) => b.intel - a.intel);
const maxIntel = 57;

// Speed data sorted by speed desc (exclude Muse Spark - no speed data)
const speedData = models.filter(m => m.speed !== null).sort((a, b) => b.speed - a.speed);
const maxSpeed = 206;

// Price data sorted by price asc (exclude Muse Spark)
const priceData = models.filter(m => m.price !== null).sort((a, b) => a.price - b.price);
const maxPrice = 10.00;

// ─── RENDER BAR CHARTS ───
function renderBarChart(containerId, data, valueKey, maxVal, unit, colorFn, formatFn) {
  const container = document.getElementById(containerId);
  let html = '';
  data.forEach((d, i) => {
    const val = d[valueKey];
    const pct = (val / maxVal) * 100;
    const minPct = Math.max(pct, 8);
    const barColor = typeof colorFn === 'function' ? colorFn(d, i) : d.color;
    const displayVal = formatFn ? formatFn(val) : val;
    const isSmall = pct < 20;
    html += `<div class="bar-row">
      <div class="bar-label">${d.short || d.name}</div>
      <div class="bar-track">
        <div class="bar-fill" style="width:${minPct}%;background:${barColor};">
          ${!isSmall ? `<span class="bar-val">${displayVal}</span>` : ''}
        </div>
      </div>
      ${isSmall ? `<span class="bar-val-outside" style="color:${barColor};">${displayVal}</span>` : ''}
    </div>`;
  });
  container.innerHTML = html;
}

// Intelligence bars (blue gradient)
renderBarChart('intel-chart', intelData, 'intel', maxIntel, '',
  (d, i) => {
    const colors = ['#3b82f6','#3b82f6','#2563eb','#7c3aed','#6366f1','#0d9488','#ec4899','#14b8a6','#8b5cf6','#22c55e','#64748b'];
    return d.color;
  },
  v => v
);

// Speed bars (teal gradient)
renderBarChart('speed-chart', speedData, 'speed', maxSpeed, ' tok/s',
  (d, i) => d.color,
  v => v + ' tok/s'
);

// Price chart - horizontal, all in one row
function renderPriceChart() {
  const container = document.getElementById('price-chart');
  let html = '';
  priceData.forEach((d, i) => {
    const pct = (d.price / maxPrice) * 100;
    const minPct = Math.max(pct, 6);
    const barColor = d.color;
    const isSmall = pct < 15;
    html += `<div class="bar-row">
      <div class="bar-label">${d.short || d.name}</div>
      <div class="bar-track">
        <div class="bar-fill" style="width:${minPct}%;background:${barColor};">
          ${!isSmall ? `<span class="bar-val">$${d.price.toFixed(2)}</span>` : ''}
        </div>
      </div>
      ${isSmall ? `<span class="bar-val-outside" style="color:${barColor};">$${d.price.toFixed(2)}</span>` : ''}
    </div>`;
  });
  container.innerHTML = html;
}
renderPriceChart();

// ─── BUBBLE CHART (Trade-off Analysis) ───
function renderBubbleChart() {
  const svg = document.getElementById('bubble-svg');
  const W = 2100, H = 600;
  const pad = { top: 30, right: 80, bottom: 60, left: 80 };
  const plotW = W - pad.left - pad.right;
  const plotH = H - pad.top - pad.bottom;

  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);

  const bubbleData = models.filter(m => m.speed !== null && m.price !== null);

  const xMin = 20, xMax = 220;
  const yMin = 25, yMax = 62;
  const rMin = 14, rMax = 48;

  function xScale(v) { return pad.left + ((v - xMin) / (xMax - xMin)) * plotW; }
  function yScale(v) { return pad.top + plotH - ((v - yMin) / (yMax - yMin)) * plotH; }
  function rScale(v) { return rMin + ((v - 0.3) / (10 - 0.3)) * (rMax - rMin); }

  let svgContent = '';

  // Grid lines
  for (let y = 30; y <= 60; y += 10) {
    const py = yScale(y);
    svgContent += `<line x1="${pad.left}" y1="${py}" x2="${W - pad.right}" y2="${py}" stroke="rgba(255,255,255,0.05)" stroke-width="1"/>`;
    svgContent += `<text x="${pad.left - 16}" y="${py + 5}" fill="#475569" font-size="14" text-anchor="end" font-family="JetBrains Mono, monospace">${y}</text>`;
  }
  for (let x = 50; x <= 200; x += 50) {
    const px = xScale(x);
    svgContent += `<line x1="${px}" y1="${pad.top}" x2="${px}" y2="${H - pad.bottom}" stroke="rgba(255,255,255,0.05)" stroke-width="1"/>`;
    svgContent += `<text x="${px}" y="${H - pad.bottom + 24}" fill="#475569" font-size="14" text-anchor="middle" font-family="JetBrains Mono, monospace">${x}</text>`;
  }

  // Axis labels
  svgContent += `<text x="${W / 2}" y="${H - 8}" fill="#64748b" font-size="16" text-anchor="middle" font-family="Inter, sans-serif" font-weight="500">Output Speed (tokens/sec) →</text>`;
  svgContent += `<text x="18" y="${H / 2}" fill="#64748b" font-size="16" text-anchor="middle" font-family="Inter, sans-serif" font-weight="500" transform="rotate(-90, 18, ${H/2})">← Intelligence Score</text>`;

  // Axes
  svgContent += `<line x1="${pad.left}" y1="${H - pad.bottom}" x2="${W - pad.right}" y2="${H - pad.bottom}" stroke="rgba(255,255,255,0.1)" stroke-width="1.5"/>`;
  svgContent += `<line x1="${pad.left}" y1="${pad.top}" x2="${pad.left}" y2="${H - pad.bottom}" stroke="rgba(255,255,255,0.1)" stroke-width="1.5"/>`;

  // Bubbles sorted by price descending so smaller bubbles render on top
  const sortedData = [...bubbleData].sort((a, b) => b.price - a.price);

  sortedData.forEach(d => {
    const cx = xScale(d.speed);
    const cy = yScale(d.intel);
    const r = rScale(d.price);

    svgContent += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${d.color}" fill-opacity="0.25" stroke="${d.color}" stroke-width="2" stroke-opacity="0.7"/>`;

    // Label positioning
    let labelX = cx;
    let labelY = cy - r - 10;
    let anchor = 'middle';

    // Adjust labels to avoid overlap
    if (d.short === 'gpt-oss-120B') { labelX = cx - 10; labelY = cy - r - 12; anchor = 'end'; }
    if (d.short === 'Nemotron 3') { labelX = cx + 10; labelY = cy + r + 20; anchor = 'start'; }
    if (d.short === 'Claude Opus 4.6') { labelX = cx + r + 12; labelY = cy + 5; anchor = 'start'; }
    if (d.short === 'Claude Sonnet 4.6') { labelX = cx + r + 12; labelY = cy + 5; anchor = 'start'; }
    if (d.short === 'GLM-5.1') { labelX = cx - r - 12; labelY = cy + 5; anchor = 'end'; }
    if (d.short === 'DeepSeek V3.2') { labelX = cx - r - 10; labelY = cy - 5; anchor = 'end'; }
    if (d.short === 'GPT-5.4') { labelX = cx + r + 12; labelY = cy; anchor = 'start'; }
    if (d.short === 'Gemini 3.1 Pro') { labelX = cx - r - 12; labelY = cy; anchor = 'end'; }

    svgContent += `<text x="${labelX}" y="${labelY}" fill="${d.color}" font-size="15" text-anchor="${anchor}" font-family="Inter, sans-serif" font-weight="600">${d.short}</text>`;
    svgContent += `<text x="${labelX}" y="${labelY + 16}" fill="#64748b" font-size="12" text-anchor="${anchor}" font-family="JetBrains Mono, monospace">$${d.price.toFixed(2)}</text>`;
  });

  // Legend for bubble size
  svgContent += `<text x="${W - pad.right - 10}" y="${pad.top + 20}" fill="#475569" font-size="13" text-anchor="end" font-family="Inter, sans-serif">Bubble size = cost per 1M tokens</text>`;

  svg.innerHTML = svgContent;
}
renderBubbleChart();
</script>
</body>
</html>
