const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--font-render-hinting=none'],
  });

  const page = await browser.newPage();

  // A1 portrait at 100 DPI ≈ 2384×3370px — match the HTML body dimensions
  await page.setViewport({ width: 2384, height: 3370, deviceScaleFactor: 1 });

  const htmlPath = path.resolve(__dirname, 'poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for fonts and rendering
  await page.evaluate(() => document.fonts?.ready);
  await new Promise(r => setTimeout(r, 1500));

  await page.screenshot({
    path: path.resolve(__dirname, 'final_poster.png'),
    fullPage: false,
    clip: { x: 0, y: 0, width: 2384, height: 3370 },
    type: 'png',
  });

  console.log('Poster saved to final_poster.png');
  await browser.close();
})();

